from collections import deque

def bfs(graph, start):
    dist = {start: 0}
    queue = deque([start])
    while queue:
        node = queue.popleft()
        for nxt in graph[node]:
            if nxt not in dist:          # mark when you enqueue
                dist[nxt] = dist[node] + 1
                queue.append(nxt)
    return dist

g = {'A': ['B', 'C'], 'B': ['D'], 'C': ['D'], 'D': []}
print(bfs(g, 'A')['D'])  # -> 2

